function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value is an integer between -100000 and 100000.';
  return null;
}

