function waysToSplitArray(nums) {
  let total = 0;
  for (const value of nums) {
    total += value;
  }

  let leftSum = 0;
  let ways = 0;
  for (let i = 0; i < nums.length - 1; i++) {
    leftSum += nums[i];
    const rightSum = total - leftSum;
    if (leftSum >= rightSum) {
      ways++;
    }
  }
  return ways;
}

