function waysToSplitArray(nums) {
  let count = 0;
  for (let cut = 1; cut < nums.length; cut++) {
    const left = nums.slice(0, cut).reduce((a, b) => a + b, 0);
    const right = nums.slice(cut).reduce((a, b) => a + b, 0);
    if (left >= right) count++;
  }
  return count;
}

