function generate(rand, size) {
  const large = size === 'large';
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = large ? pick(1500, 2000) : pick(2, 9);
  const limit = large ? 100000 : rand() < 0.2 ? 100000 : 6;
  // A bias toward positive or negative values moves where the valid cuts begin.
  const bias = rand() < 0.5 ? 0 : (rand() < 0.5 ? 1 : -1) * rand() * 0.6;
  const nums = Array.from({ length: n }, () => {
    const value = Math.round((rand() * 2 - 1 + bias) * limit);
    return Math.max(-limit, Math.min(limit, value));
  });
  return [nums];
}
